package com.mantou.salesdialer.contacts;
/** Delegates production clock/window/30s guards; rehearsal uses an explicitly anchored business clock. */
public final class EnterpriseTimerTicket {
 private final boolean controlledException;public final WorkspaceTimerModel.Ticket ticket;public final long phoneWallAtArm,businessAtArm;public final String owner,queueId,accountKey;
 public EnterpriseTimerTicket(long version,long dueBusiness,long business,long phoneWall,long elapsed,String boot,String token,String owner,String queue,String account){this(version,dueBusiness,business,phoneWall,elapsed,boot,token,owner,queue,account,false);}
 public EnterpriseTimerTicket(long version,long dueBusiness,long business,long phoneWall,long elapsed,String boot,String token,String owner,String queue,String account,boolean controlledException){this.controlledException=controlledException;if(owner==null||!owner.matches("[a-f0-9]{64}")||queue==null||!queue.matches("QUEUE-[a-f0-9-]{36}")||account==null||!account.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("INVALID_ENTERPRISE_TICKET");phoneWallAtArm=phoneWall;businessAtArm=business;this.owner=owner;queueId=queue;accountKey=account;long dueElapsed;try{dueElapsed=Math.addExact(elapsed,Math.subtractExact(dueBusiness,business));}catch(ArithmeticException e){throw new IllegalArgumentException("INVALID_ENTERPRISE_TICKET");}ticket=new WorkspaceTimerModel.Ticket(version,dueBusiness,dueElapsed,boot,token,controlledException);}
 public String status(long wall,long elapsed,String boot,String currentOwner,long version){if(!owner.equals(currentOwner))return "OWNER_CHANGED";long business;try{business=Math.addExact(businessAtArm,Math.subtractExact(wall,phoneWallAtArm));}catch(ArithmeticException e){return "TIMER_CLOCK_CHANGED";}return WorkspaceTimerModel.status(ticket,version,ticket.token,business,elapsed,boot,controlledException);}
}
